//! The rc2s2 wire format: protobuf definitions under `proto/`, generated by prost and tonic.
//! The Android client generates Kotlin from the same files.

pub mod event {
    pub mod v1 {
        tonic::include_proto!("rc2s2.event.v1");
    }
}

pub mod node {
    pub mod v1 {
        tonic::include_proto!("rc2s2.node.v1");
    }
}

pub mod control {
    pub mod v1 {
        tonic::include_proto!("rc2s2.control.v1");
    }
}
